    {
        var request = new GetPreSignedUrlRequest
        {
            BucketName = _bucketName,
            Key = fileName,
            Expires = System.DateTime.UtcNow.AddHours(1) // URL valid for 1 hour
        };

        return Task.FromResult(_s3Client.GetPreSignedURL(request));
    }
