package main

import (
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/websocket"
)

// WebSocket upgrader
var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		return true
	},
}

// Client structure
type Client struct {
	ID       string
	Username string
	Conn     *websocket.Conn
}

// Message structure
type Message struct {
	SenderID string \`json:"senderID"\`
	Username string \`json:"username"\`
	Text     string \`json:"text"\`
}

var (
	clients   = make(map[string]*Client)
	clientsMu sync.Mutex
	broadcast = make(chan Message)
)

// Handle WebSocket connections
func handleConnections(w http.ResponseWriter, r *http.Request) {
	// Upgrade the HTTP connection to WebSocket
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Printf("Error upgrading connection: %v", err)
		return
	}
	defer conn.Close()

	// Receive the username as the first message
	var initMessage Message
	err = conn.ReadJSON(&initMessage)
	if err != nil {
		log.Printf("Error reading initial message: %v", err)
		return
	}

	client := &Client{
		ID:       conn.RemoteAddr().String(),
		Username: initMessage.Username,
		Conn:     conn,
	}

	// Add the client to the list
	clientsMu.Lock()
	clients[client.ID] = client
	clientsMu.Unlock()

	log.Printf("New client connected: %s (%s)", client.ID, client.Username)

	// Listen for messages from the client
	for {
		var msg Message
		err := conn.ReadJSON(&msg)
		if err != nil {
			log.Printf("Error reading JSON: %v", err)
			break
		}
		msg.SenderID = client.ID
		msg.Username = client.Username
		broadcast <- msg
	}

	// Remove the client from the list when disconnected
	clientsMu.Lock()
	delete(clients, client.ID)
	clientsMu.Unlock()
	log.Printf("Client disconnected: %s (%s)", client.ID, client.Username)
}

// Broadcast messages to all clients
func handleMessages() {
	for {
		msg := <-broadcast
		clientsMu.Lock()
		for _, client := range clients {
			err := client.Conn.WriteJSON(msg)
			if err != nil {
				log.Printf("Error sending message: %v", err)
				client.Conn.Close()
				delete(clients, client.ID)
			}
		}
		clientsMu.Unlock()
	}
}

func main() {
	// Serve static files (like index.html)
	http.Handle("/", http.FileServer(http.Dir("./static")))

	// WebSocket handler
	http.HandleFunc("/ws", handleConnections)

	// Start the server
	log.Println("Server started on :8080")
	go handleMessages()
	err := http.ListenAndServe(":8080", nil)
	if err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}

